export function taskLabel(name: string, completed: boolean): string {
  return (completed ? '[x] ' : '[ ] ') + name;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

test('completed task has [x] prefix', () => {
  assert.equal(taskLabel('draft', true), '[x] draft');
});

test('incomplete task keeps [ ] prefix', () => {
  assert.equal(taskLabel('draft', false), '[ ] draft');
});

test('preserves name exactly with special characters and whitespace', () => {
  assert.equal(taskLabel('review PR #123 (urgent!)', true), '[x] review PR #123 (urgent!)');
  assert.equal(taskLabel('', false), '[ ] ');
  assert.equal(taskLabel('  leading and trailing  ', true), '[x]   leading and trailing  ');
});

